import { Request, Response, Router } from 'express';
import { AdvanceOrderUseCase } from '../../application/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../../application/CancelOrderUseCase';
import { GetOrderUseCase } from '../../application/GetOrderUseCase';
import { ListOrdersUseCase } from '../../application/ListOrdersUseCase';
import { PlaceOrderUseCase } from '../../application/PlaceOrderUseCase';
import { OrderState } from '../../domain/OrderState';
import { parseOptionalState, parsePlaceOrderCommand } from './requestParsers';

type OrderParams = { id: string };

/** Maps action path segments to the fulfilment state they move an order into. */
const ADVANCE_ACTIONS: ReadonlyArray<[string, OrderState]> = [
  ['pay', 'paid'],
  ['pack', 'packed'],
  ['ship', 'shipped'],
  ['deliver', 'delivered'],
];

export interface OrderUseCases {
  placeOrder: PlaceOrderUseCase;
  advanceOrder: AdvanceOrderUseCase;
  cancelOrder: CancelOrderUseCase;
  getOrder: GetOrderUseCase;
  listOrders: ListOrdersUseCase;
}

export class OrderController {
  constructor(private readonly useCases: OrderUseCases) {}

  routes(): Router {
    const router = Router();
    router.post('/', (req, res) => this.place(req, res));
    router.get('/', (req, res) => this.list(req, res));
    router.get('/:id', (req: Request<OrderParams>, res) => this.get(req, res));
    for (const [action, target] of ADVANCE_ACTIONS) {
      router.post(`/:id/${action}`, (req: Request<OrderParams>, res) => this.advance(req, res, target));
    }
    router.post('/:id/cancel', (req: Request<OrderParams>, res) => this.cancel(req, res));
    return router;
  }

  private place(req: Request, res: Response): void {
    const order = this.useCases.placeOrder.execute(parsePlaceOrderCommand(req.body));
    res.status(201).location(`/orders/${order.id}`).json(order);
  }

  private list(req: Request, res: Response): void {
    res.json(this.useCases.listOrders.execute(parseOptionalState(req.query.state)));
  }

  private get(req: Request<OrderParams>, res: Response): void {
    res.json(this.useCases.getOrder.execute(req.params.id));
  }

  private advance(req: Request<OrderParams>, res: Response, target: OrderState): void {
    res.json(this.useCases.advanceOrder.execute(req.params.id, target));
  }

  private cancel(req: Request<OrderParams>, res: Response): void {
    res.json(this.useCases.cancelOrder.execute(req.params.id));
  }
}

