import { ErrorRequestHandler, RequestHandler } from 'express';
import { NotFoundError, ValidationError } from '../../application/errors';
import {
  DomainError,
  EmptyOrderError,
  InsufficientStockError,
  InvalidOrderTransitionError,
  InvalidQuantityError,
  UnknownProductError,
} from '../../domain/errors';

function statusFor(error: unknown): number {
  if (error instanceof NotFoundError) return 404;
  if (error instanceof ValidationError) return 400;
  if (error instanceof InvalidQuantityError || error instanceof EmptyOrderError) return 400;
  if (error instanceof UnknownProductError) return 422;
  if (error instanceof InsufficientStockError || error instanceof InvalidOrderTransitionError) return 409;
  if (error instanceof DomainError) return 422;
  if (error instanceof SyntaxError) return 400;
  return 500;
}

export const notFoundHandler: RequestHandler = (req, res) => {
  res.status(404).json({ error: 'NotFound', message: `No route for ${req.method} ${req.path}` });
};

export const errorHandler: ErrorRequestHandler = (error: unknown, _req, res, _next) => {
  const status = statusFor(error);
  if (status === 500) {
    console.error(error);
    res.status(500).json({ error: 'InternalServerError', message: 'Unexpected error' });
    return;
  }
  const { name, message } = error as Error;
  res.status(status).json({ error: name, message });
};

