import { PlaceOrderCommand, PlaceOrderLineCommand } from '../../application/dto';
import { ValidationError } from '../../application/errors';
import { isOrderState, OrderState } from '../../domain/OrderState';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function parseLine(value: unknown, index: number): PlaceOrderLineCommand {
  if (!isRecord(value)) {
    throw new ValidationError(`lines[${index}] must be an object`);
  }
  const { productId, quantity } = value;
  if (typeof productId !== 'string' || productId.trim() === '') {
    throw new ValidationError(`lines[${index}].productId must be a non-empty string`);
  }
  if (typeof quantity !== 'number') {
    throw new ValidationError(`lines[${index}].quantity must be a number`);
  }
  return { productId, quantity };
}

export function parsePlaceOrderCommand(body: unknown): PlaceOrderCommand {
  if (!isRecord(body)) {
    throw new ValidationError('Request body must be a JSON object');
  }
  const { customerId, lines } = body;
  if (typeof customerId !== 'string' || customerId.trim() === '') {
    throw new ValidationError('customerId must be a non-empty string');
  }
  if (!Array.isArray(lines) || lines.length === 0) {
    throw new ValidationError('lines must be a non-empty array');
  }
  return { customerId, lines: lines.map(parseLine) };
}

export function parseOptionalState(value: unknown): OrderState | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== 'string' || !isOrderState(value)) {
    throw new ValidationError(`state must be one of the known order states`);
  }
  return value;
}

